enum Spell {
    FIREBALL(80), FROST(60), THUNDER(90), HEAL(0);
    private final int damage;
    Spell(int d) { this.damage = d; }
    public int getDamage() { return damage; }
}

String school = switch (Spell.THUNDER) {
    case FIREBALL -> "Fire";
    case FROST    -> "Ice";
    case THUNDER  -> "Storm";
    case HEAL     -> "Holy";
};
System.out.println(school); // Storm

