System.out.println(bolt.power()); // 75

record Spell(String name, int power) {
    Spell {
        if (power < 0) throw new IllegalArgumentException();
    }
}

Spell a = new Spell("Frost", 60);
Spell b = new Spell("Frost", 60);
System.out.println(a.equals(b)); // true

